// newRetryingRawClient returns a RawClient whose transport retries quickly
// so body replay can be exercised without real backoff delays.
func newRetryingRawClient(t *testing.T, srv *httptest.Server) *RawClient {
	t.Helper()

	policy := RetryPolicy{
		MaxAttempts: 3,
		BaseDelay:   time.Millisecond,
		MaxDelay:    time.Millisecond,
	}
	httpClient := NewHTTPClient(Config{
		BaseURL:     srv.URL,
		HTTPClient:  srv.Client(),
		RetryPolicy: &policy,
	})
	raw, err := NewRawClient(srv.URL, httpClient)
	if err != nil {
		t.Fatalf("NewRawClient error: %v", err)
	}
	return raw
}

// rateLimitOnceServer answers the first request with 429 and every later
// request with 200, recording each request body and Content-Length.
func rateLimitOnceServer(t *testing.T) (*httptest.Server, func() ([]string, []int64)) {
	t.Helper()

	var (
		mu      sync.Mutex
		bodies  []string
		lengths []int64
	)
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, err := io.ReadAll(r.Body)
		if err != nil {
			t.Errorf("read request body: %v", err)
		}
		mu.Lock()
		bodies = append(bodies, string(body))
		lengths = append(lengths, r.ContentLength)
		n := len(bodies)
		mu.Unlock()

		if n == 1 {
			w.Header().Set("Retry-After", "0")
			w.WriteHeader(http.StatusTooManyRequests)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"ok":true}`))
	}))
	t.Cleanup(srv.Close)

	return srv, func() ([]string, []int64) {
		mu.Lock()
		defer mu.Unlock()
		return append([]string(nil), bodies...), append([]int64(nil), lengths...)
	}
}

func TestRawClient_Do_ReplaysFileBodyOnRetry(t *testing.T) {
	t.Parallel()

	srv, recorded := rateLimitOnceServer(t)
	raw := newRetryingRawClient(t, srv)

	path := filepath.Join(t.TempDir(), "upload.bin")
	if err := os.WriteFile(path, []byte("file-payload"), 0o600); err != nil {
		t.Fatalf("write file: %v", err)
	}
	f, err := os.Open(path)
	if err != nil {
		t.Fatalf("open file: %v", err)
	}
	defer f.Close()

	var out struct {
		Ok bool `json:"ok"`
	}
	if err := raw.Do(context.Background(), http.MethodPost, "/files", nil, f, &out, WithHeader("Content-Type", "application/octet-stream")); err != nil {
		t.Fatalf("Do error: %v", err)
	}
	if !out.Ok {
		t.Fatalf("expected ok=true")
	}

	bodies, lengths := recorded()
	if len(bodies) != 2 {
		t.Fatalf("expected 2 attempts, got %d", len(bodies))
	}
	for i, body := range bodies {
		if body != "file-payload" {
			t.Fatalf("attempt %d: unexpected body %q", i+1, body)
		}
		if lengths[i] != int64(len("file-payload")) {
			t.Fatalf("attempt %d: expected Content-Length %d, got %d", i+1, len("file-payload"), lengths[i])
		}
	}

	// The body passed to Do is closed once the request completes, matching
	// what net/http does with a request body that implements io.Closer.
	if _, err := f.Read(make([]byte, 1)); !errors.Is(err, os.ErrClosed) {
		t.Fatalf("expected file to be closed after Do, got %v", err)
	}
