	// of the reader types http.NewRequest knows how to replay itself.
	body := io.NewSectionReader(strings.NewReader("skip-payload"), 0, int64(len("skip-payload")))
	if _, err := body.Seek(int64(len("skip-")), io.SeekStart); err != nil {
