			t.Fatalf("attempt %d: unexpected body %q", i+1, got)
		}
		if lengths[i] != int64(len("payload")) {
			t.Fatalf("attempt %d: expected Content-Length %d, got %d", i+1, len("payload"), lengths[i])
		}
	}
}

func TestRawClient_Do_DoesNotRetryUnreplayableBody(t *testing.T) {
	t.Parallel()

	srv, recorded := rateLimitOnceServer(t)
	raw := newRetryingRawClient(t, srv)

	// A plain io.Reader cannot be rewound, so the request is sent once and
	// the 429 surfaces instead of a second attempt with an empty body.
	body := struct{ io.Reader }{strings.NewReader("once")}
	err := raw.Do(context.Background(), http.MethodPost, "/x", nil, body, nil)
	var rlErr *RateLimitError
	if !errors.As(err, &rlErr) {
		t.Fatalf("expected RateLimitError, got %T (%v)", err, err)
	}

	bodies, _ := recorded()
	if len(bodies) != 1 {
		t.Fatalf("expected 1 attempt, got %d", len(bodies))
	}
	if bodies[0] != "once" {
		t.Fatalf("unexpected body %q", bodies[0])
	}
}
