			t.Fatalf("NewRequest error: %v", err)
		}
		_ = replayableBody(req, body)
		if req.Body != http.NoBody || req.ContentLength != 0 {
			t.Fatalf("expected NoBody with zero length, got %T (%d)", req.Body, req.ContentLength)
		}
		replay, err := req.GetBody()
		if err != nil || replay != http.NoBody {
			t.Fatalf("expected NoBody replay, got %T (%v)", replay, err)
		}
	})
}
